"""Instruction pipeline module boundary."""

from survival_infra.pipeline.instructions.repository import InstructionRepository
from survival_infra.pipeline.instructions.service import (
    DuplicateInstructionSourceError,
    InstructionService,
    PayloadTooLargeError,
    UnsupportedUploadTypeError,
)


class InstructionModule:
    def __init__(self, data_dir: str, max_upload_bytes: int = 52428800):
        self.repository = InstructionRepository(data_dir)
        self.service = InstructionService(self.repository, max_upload_bytes=max_upload_bytes)

    def _result(self, status: str, http_status: int, payload):
        return {"status": status, "http_status": http_status, "payload": payload}

    def ingest_source(self, payload: dict, files=None):
        upload = None
        if files is not None:
            upload = files.get("file")

        try:
            row = self.service.ingest_source(payload or {}, upload=upload)
        except DuplicateInstructionSourceError as exc:
            return self._result(
                "duplicate",
                409,
                {"error": "duplicate", "existing_instruction_id": exc.existing_instruction_id},
            )
        except PayloadTooLargeError as exc:
            return self._result("invalid_request", 413, {"error": str(exc)})
        except UnsupportedUploadTypeError as exc:
            return self._result("invalid_request", 415, {"error": str(exc)})
        except ValueError as exc:
            return self._result("invalid_request", 400, {"error": str(exc)})

        return self._result(
            "created",
            201,
            {
                "instruction_id": row.get("instruction_id"),
                "source_type": row.get("source_type"),
                "fingerprint": row.get("fingerprint"),
                "captured_at": row.get("captured_at"),
                "status": row.get("status", "INGESTED"),
            },
        )

    def list_sources(self, source_type: str | None = None, limit: int | None = None):
        try:
            payload = self.service.list_sources(source_type, limit)
        except ValueError as exc:
            return self._result("invalid_request", 400, {"error": str(exc)})
        return self._result("ok", 200, payload)

    def get_source(self, instruction_id: str):
        try:
            payload = self.service.get_source(instruction_id)
        except ValueError as exc:
            return self._result("invalid_request", 400, {"error": str(exc)})
        if payload is None:
            return self._result("not_found", 404, {"error": "not found"})
        return self._result("ok", 200, payload)

    def get_source_file_access(self, instruction_id: str):
        try:
            payload = self.service.get_source_file_access(instruction_id)
        except ValueError as exc:
            return self._result("invalid_request", 400, {"error": str(exc)})

        status = payload.get("status")
        if status == "not_found":
            return self._result("not_found", 404, {"error": "not found"})
        if status == "not_file_upload":
            return self._result("not_file_upload", 400, {"error": "not a file upload"})
        if status == "file_not_found":
            return self._result("file_not_found", 404, {"error": "file not found"})
        return self._result("ok", 200, payload)

"""Instruction source ingest service logic."""

import hashlib
import json
import re
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

from survival_infra.pipeline.instructions.repository import InstructionRepository


SUPPORTED_SOURCE_TYPES = {"freeform", "url_note", "citation_note", "file_upload"}
SUPPORTED_UPLOAD_MIME_TYPES = {
    "text/plain",
    "text/markdown",
    "application/pdf",
    "application/octet-stream",
}
UNSAFE_FALLBACK_MIME_TYPES = {
    "application/octet-stream",
    "application/x-msdownload",
    "application/x-sh",
}
MAX_TITLE_LENGTH = 255


class DuplicateInstructionSourceError(ValueError):
    def __init__(self, existing_instruction_id: str):
        super().__init__("duplicate")
        self.existing_instruction_id = existing_instruction_id


class PayloadTooLargeError(ValueError):
    pass


class UnsupportedUploadTypeError(ValueError):
    pass


class InstructionService:
    def __init__(self, repository: InstructionRepository, max_upload_bytes: int = 52428800):
        self.repository = repository
        self.max_upload_bytes = max_upload_bytes

    def _normalize_text(self, value: str | None) -> str:
        return re.sub(r"\s+", " ", str(value or "").strip())

    def _normalize_title(self, value: str | None) -> str:
        title = self._normalize_text(value)
        if len(title) > MAX_TITLE_LENGTH:
            raise ValueError("title exceeds max length")
        return title

    def _canonical_url(self, value: str) -> str:
        raw = self._normalize_text(value)
        if not raw:
            raise ValueError("url is required")

        parsed = urlsplit(raw)
        if not parsed.scheme or not parsed.netloc:
            raise ValueError("url is invalid")

        scheme = parsed.scheme.lower()
        host = parsed.hostname.lower() if parsed.hostname else ""
        port = parsed.port
        if port and ((scheme == "http" and port != 80) or (scheme == "https" and port != 443)):
            netloc = f"{host}:{port}"
        else:
            netloc = host

        path = parsed.path or "/"
        if len(path) > 1 and path.endswith("/"):
            path = path.rstrip("/")

        query_pairs = parse_qsl(parsed.query, keep_blank_values=True)
        query_pairs.sort()
        query = urlencode(query_pairs)

        return urlunsplit((scheme, netloc, path, query, ""))

    def _fingerprint_from_object(self, payload: dict) -> str:
        canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
        return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    def _normalize_citation(self, citation: dict) -> dict:
        if not isinstance(citation, dict):
            raise ValueError("citation is required")

        normalized = {
            "title": self._normalize_text(citation.get("title")),
            "author": self._normalize_text(citation.get("author")),
            "chapter": self._normalize_text(citation.get("chapter")),
            "page": self._normalize_text(citation.get("page")),
            "edition": self._normalize_text(citation.get("edition")),
        }
        if not normalized["title"]:
            raise ValueError("citation.title is required")
        return normalized

    def _ensure_not_duplicate(self, fingerprint: str):
        existing = self.repository.find_by_fingerprint(fingerprint)
        if existing is not None:
            raise DuplicateInstructionSourceError(existing.get("instruction_id", ""))

    def _ingest_text_based(self, source_type: str, payload: dict):
        title = self._normalize_title(payload.get("title"))
        notes = self._normalize_text(payload.get("notes"))

        if not notes:
            raise ValueError("notes is required")

        row = {
            "source_type": source_type,
            "title": title,
            "notes": notes,
            "status": "INGESTED",
        }

        if source_type == "freeform":
            fingerprint = self._fingerprint_from_object({"source_type": source_type, "notes": notes})
        elif source_type == "url_note":
            canonical_url = self._canonical_url(payload.get("url") or "")
            row["url"] = canonical_url
            fingerprint = self._fingerprint_from_object(
                {"source_type": source_type, "url": canonical_url, "notes": notes}
            )
        elif source_type == "citation_note":
            citation = self._normalize_citation(payload.get("citation"))
            row["citation"] = citation
            fingerprint = self._fingerprint_from_object(
                {"source_type": source_type, "citation": citation, "notes": notes}
            )
        else:
            raise ValueError("unsupported source_type")

        row["fingerprint"] = fingerprint
        self._ensure_not_duplicate(fingerprint)
        return self.repository.append_source(row)

    def _ingest_file_upload(self, payload: dict, upload):
        if upload is None:
            raise ValueError("file is required")

        title = self._normalize_title(payload.get("title"))
        notes = self._normalize_text(payload.get("notes"))
        content_type = (upload.mimetype or "application/octet-stream").lower()

        if content_type not in SUPPORTED_UPLOAD_MIME_TYPES:
            raise UnsupportedUploadTypeError("unsupported upload content type")

        file_bytes = upload.read()
        if len(file_bytes) > self.max_upload_bytes:
            raise PayloadTooLargeError(f"file exceeds size limit ({self.max_upload_bytes} bytes)")

        sha256_hex = hashlib.sha256(file_bytes).hexdigest()
        self._ensure_not_duplicate(sha256_hex)

        file_ref = self.repository.save_upload_bytes(
            file_bytes=file_bytes,
            original_filename=(upload.filename or "upload.bin"),
            content_type=content_type,
            sha256_hex=sha256_hex,
        )

        row = {
            "source_type": "file_upload",
            "title": title,
            "notes": notes,
            "fingerprint": sha256_hex,
            "file_ref": file_ref,
            "status": "INGESTED",
        }
        return self.repository.append_source(row)

    def ingest_source(self, payload: dict, upload=None):
        source_type = self._normalize_text(payload.get("source_type"))
        if source_type not in SUPPORTED_SOURCE_TYPES:
            raise ValueError("unsupported source_type")

        if source_type == "file_upload":
            return self._ingest_file_upload(payload, upload)
        return self._ingest_text_based(source_type, payload)

    def list_sources(self, source_type: str | None = None, limit: int | None = None):
        normalized_type = self._normalize_text(source_type) if source_type is not None else None
        if normalized_type and normalized_type not in SUPPORTED_SOURCE_TYPES:
            raise ValueError("unsupported source_type")
        if limit is None:
            limit = 50
        if limit < 1:
            raise ValueError("limit must be >= 1")
        return self.repository.list_sources(normalized_type, limit)

    def get_source(self, instruction_id: str):
        instruction_id = self._normalize_text(instruction_id)
        if not instruction_id:
            raise ValueError("instruction_id is required")
        return self.repository.get_source(instruction_id)

    def _is_inline_preview_supported(self, content_type: str) -> bool:
        normalized = self._normalize_text(content_type).lower()
        if not normalized:
            return False
        if normalized in UNSAFE_FALLBACK_MIME_TYPES:
            return False
        if normalized.startswith("image/"):
            return True
        if normalized.startswith("text/"):
            return True
        if normalized in {"application/pdf", "application/json", "application/xml"}:
            return True
        return False

    def get_source_file_access(self, instruction_id: str):
        source = self.get_source(instruction_id)
        if source is None:
            return {"status": "not_found"}
        if source.get("source_type") != "file_upload":
            return {"status": "not_file_upload", "source": source}

        file_ref = source.get("file_ref") or {}
        file_path = self.repository.resolve_upload_path(file_ref.get("stored_path"))
        if not file_path:
            return {"status": "file_not_found", "source": source}

        content_type = self._normalize_text(file_ref.get("content_type") or "application/octet-stream").lower()
        preview_supported = self._is_inline_preview_supported(content_type)
        return {
            "status": "ok",
            "source": source,
            "file_path": file_path,
            "content_type": content_type,
            "original_filename": file_ref.get("original_filename") or "download",
            "preview_supported": preview_supported,
            "preview_mode": "inline" if preview_supported else "fallback",
            "preview_reason": "unsupported or unsafe content type" if not preview_supported else "",
        }
